"OLAYLAR_2S_0919:1611-01-01:0":{"b": ["شاہ عباس اول نے مازندران میں فرح آباد شہر کی بنیاد رکھی", "cab4d0fe"], "d": ["صفوی حکمران عباس اول نے مازندران میں بحیرۂ خزر کے قریب فرح آباد شہر تعمیر کروایا اور ملک کے چاروں اطراف سے لوگوں کو یہاں بسایا۔ تعمیر 1020/1611 میں شروع ہوئی۔", "cc05c705"]},
"OLAYLAR_2S_0919:1631-01-01:0":{"b": ["دریائے Angara پر روسی Bratsk کا قلعہ تعمیر ہوا", "e7b4be59"], "d": ["روس کی مشرقی سائبیریا کی طرف پیش قدمی کے دوران دریائے Angara پر Bratsk کا قلعہ تعمیر ہوا۔", "eb1a1abd"]},
"OLAYLAR_2S_0919:1658-03-08:0":{"b": ["Roskilde کا معاہدہ — Skåne، Halland، Blekinge اور Bornholm سویڈن کو منتقل ہوئے", "afcae41b"], "d": ["پہلی چارلس گستاف جنگ ختم کرنے والے Roskilde کے معاہدے پر دستخط ہوئے؛ ڈنمارک-ناروے نے Skåne، Halland، Blekinge اور Bornholm سویڈن کے حوالے کر دیے۔", "ac397fd6"]},
"OLAYLAR_2S_0919:1663-01-01:0":{"b": ["روس نے دریائے Sura پر Penza کا قلعہ قائم کیا", "49e8d90b"], "d": ["Penza، دریائے Penza اور Sura کے سنگم پر ایک بڑے قلعے کے طور پر قائم ہوا؛ 1684 کے بعد یہ Syzran دفاعی لائن کا مغربی سرا بنا۔", "afba0eaa"]},
"OLAYLAR_2S_0919:1668-01-01:0":{"b": ["Marquette نے Sault Ste. Marie میں فرانسیسی مشن قائم کیا", "86612bcd"], "d": ["یسوعی Jacques Marquette نے جھیل Superior اور جھیل Huron کے درمیان Sault Ste. Marie کی آبشاروں کے سرے پر ایک مشن قائم کیا۔", "e90cdea2"]},
"OLAYLAR_2S_0919:1668-01-01:1":{"b": ["Hudson's Bay Company کی پہلی چوکی (Waskaganish) قائم ہوئی", "07b32d57"], "d": ["James Bay میں دریائے Rupert کے دہانے پر Médard Chouart des Groseilliers نے وہ بستی قائم کی جسے بعد میں Hudson's Bay Company کی پہلی چوکی شمار کیا گیا۔", "790b2f93"]},
"OLAYLAR_2S_0919:1700-01-01:0":{"b": ["ہسپانوی نوآبادیاتی انتظامیہ نے Pitic (Hermosillo) قائم کیا", "11e5cc04"], "d": ["ہسپانوی نوآبادیاتی انتظامیہ نے ایک قدیم مقامی بستی کی جگہ ایک قصبہ قائم کیا؛ قصبے نے 1828 میں José María González de Hermosillo کا نام اختیار کیا۔", "4724e13c"]},
"OLAYLAR_2S_0919:1716-01-01:0":{"b": ["Irtysh-Om کے سنگم پر روسی Omsk قلعہ تعمیر ہوا", "13dcce5e"], "d": ["Omsk، Tobol اور Irtysh کے درمیان Ishim استحکامی لائن کے مشرقی سرے پر ایک قلعے کے طور پر قائم ہوا؛ 1804 میں شہر بنا۔", "45facb52"]},
"OLAYLAR_2S_0919:1717-11-30:0":{"b": ["Dzungars کا Lhasa پر حملہ — Lajang Khan قتل، تبت Dzungar قبضے میں", "65beea29"], "d": ["Tsering Döndup کی قیادت میں Dzungar فوج نے Hoshut حکمران Lajang Khan کے زیرِ دفاع Lhasa پر آدھی رات کے بعد ہر سمت سے حملہ کیا؛ اندر سے حمایت پا کر Dzungars نے شہر پر قبضہ کر کے لوٹا اور Potala کو بھی لوٹ لیا۔ Lajang Khan فرار کے دوران قتل ہوا؛ Dzungars نے sTag-rtse-pa کی سربراہی میں ایک کٹھ پتلی تبتی حکومت قائم کی۔", "b6dcede2"]},
"OLAYLAR_2S_0919:1720-09-24:0":{"b": ["Qing فوج Lhasa میں داخل ہوئی — Dzungar قبضہ ختم، Qing کی سرپرستی شروع", "083358c1"], "d": ["Kangxi کی تبت بھیجی گئی دو فوجوں میں سے Galbi کی قیادت میں Sichuan کے دستے نے دشوار مارچ کے بعد Lhasa پہنچ کر شہر کو بلا مزاحمت لے لیا؛ Dzungars نے اپنی ساری قوت شمال سے آنے والی Kokonor فوج کے مقابل Dam میں جمع کر رکھی تھی۔ Dzungars کے تبت سے انخلا کے ساتھ Qing نے Lhasa میں مستقل سرپرستی کا نظام قائم کیا۔", "e5c9dcf8"]},
"OLAYLAR_2S_0919:1721-01-01:0":{"b": ["Aguayo مہم نے Los Adaes کا presidio قائم کیا", "2031793a"], "d": ["Aguayo کے مارکوئس کی مہم نے Los Adaes میں ایک presidio (فوجی چوکی) قائم کی اور مشن کو دوبارہ آباد کیا؛ یہ چوکی نیو اسپین کی فرانسیسی Louisiana کے مقابل مشرقی ٹیکساس کی سرحدی چوکی بنی۔", "6ccb0ff2"]},
"OLAYLAR_2S_0919:1722-01-01:0":{"b": ["Baraba کے میدان میں روسی Kainsk چوکی قائم ہوئی", "b14552a8"], "d": ["Baraba کے میدان میں بنائے گئے تین مستقل روسی استحکامات (pas) میں سے Kainsk چوکی دریائے Om کے وسطی حصے میں اس مقام پر بنی جہاں Kainka ندی آ ملتی ہے۔", "17a78ef2"]},
